existsByUsernameOrEmail.sql:
SELECT EXISTS(
              SELECT 1 FROM admin_users WHERE (username = #{username} OR email = #{email}) AND deleted_at IS NULL
            )

findRowByKey.sql:
SELECT id, `key`, category, CAST(value_json AS CHAR) AS valueJson,
                   visibility, is_secret AS isSecret
            FROM settings WHERE `key`=#{key}

finishBatch.sql:
UPDATE inventory_import_batches
            SET success_count = #{success}, duplicate_count = #{duplicate}, invalid_count = #{invalid}
            WHERE id = #{id}

countByStatus.sql:
SELECT status, COUNT(*) AS total
            FROM inventory_items WHERE sku_id = #{skuId}
            GROUP BY status

sessionExists.sql:
SELECT EXISTS(
              SELECT 1 FROM admin_sessions
              WHERE id = #{sessionId} AND admin_user_id = #{adminUserId}
                AND revoked_at IS NULL AND expires_at > NOW(3)
            )

ban.sql:
UPDATE admin_ip_bans
            SET banned_until = DATE_ADD(NOW(3), INTERVAL #{hours} HOUR), ban_reason = #{reason}, updated_at = NOW(3)
            WHERE ip_hash = #{hash}
